from logging import getLogger

import six

import ta_ue_plugin_android.uepc.adb_proxy as adb


cmd_raw_airplane_settings_injection = "settings put global airplane_mode_on"
cmd_raw_airplane_broadcast = "am broadcast -a android.intent.action.AIRPLANE_MODE --ez state"
cmd_raw_antenna_trigger = "service call phone"
cmd_wakeup_screen = "input keyevent KEYCODE_WAKEUP"
cmd_swipe_up_screen = "input swipe 200 500 200 0"

UEs_Screen_Wakeup = [
    'QUALCOMM Lahaina for arm64',
    'QUALCOMM Kona for arm64'
]

SVC_CALL_UE_MODELS_CPU = ["SM-G977U", "SM-G977N", "SM-G986U", "SM-G960F", "SM-G977N", "SM-G988U1", "SM-G988N", "SM-G950U1"]
SVC_CALL_14_UE_MODELS = (["SAMSUNG SM-G988U", "SM-G986U1", "SAMSUNG SM-G998U", "SM-G991U1",
                          "SM-G991U", "SM-A326B", "SAMSUNG SM-G986B", "Samsung SM-G996U"], 14)
SVC_CALL_15_UE_MODELS = (["ONEPLUS LE2115", "ONEPLUS LE2125"], 15)
SVC_CALL_16_UE_MODELS = (["HUAWEI LIO-AN00", "HUAWEI ELS-AN00", "HUAWEI ANA-AN00", "HUAWEI EVR-AN00"], 16)
SVC_CALL_17_UE_MODELS = (["ONEPLUS"], 17)
SVC_CALL_25_UE_MODELS = (["XXX QTI"], 25)
SVC_CALL_28_VENDORS = ["SAMSUNG"]


class AttachDetachHandler(object):
    """Class used for handling attach and detach of UEs"""

    def __init__(self, ue_manager_protocol, serial_number, ue_model, android_version, is_rooted=False, su_prefix=None,
                 is_qualcomm=None, attach_service_call_number=None, detach_service_call_number=None):
        """
        Attach and detach handler for Android device.
        :param serial_number: (str) Devices serial number.
        :param ue_model: (str) Devices model name.
        :param android_version: Preferred "SDK number"/"API level" (int), although as legacy version name (str) is also supported.
        :param is_rooted: (bool) Flag telling if device is root enabled.
        """
        self.ueman = ue_manager_protocol
        self._sn = serial_number
        self._ue_model = ue_model
        self._android_version = android_version
        self._is_rooted = is_rooted
        self._su_prefix = su_prefix
        self._is_qualcomm_prototype = is_qualcomm
        self.attach_service_call = attach_service_call_number
        self.detach_service_call = detach_service_call_number
        self.logger = getLogger('ute_ue.uepc')
        self.logger.debug('AttachDetachHandler initialized with service calls attach={} detach={}'.format(
            attach_service_call_number, detach_service_call_number))

    def attach(self):
        """
        Attach UE with cmds selected based on: android version, ue model, root status etc.
        :return:
        """
        cmds = self._get_cmds(detach=False)
        self._run_commands(cmds)

    def detach(self):
        """
        Detach UE with cmds selected based on: android version, ue model, root status etc.
        :return:
        """
        cmds = self._get_cmds(detach=True)
        self._run_commands(cmds)

    def _run_commands(self, cmds):
        for cmd in cmds:
            result, err = adb.adb_run_cmd(self._sn, "shell", [cmd])
            self.logger.debug("Adb shell command: {} on ue: {}, result: {}, and error: {}".format(cmd, self._sn, result, err))

    def _get_cmds(self, detach=False):
        param_settings = int(detach)
        param_broadcast = str(detach).lower()
        cmds = ["{} {}".format(cmd_raw_airplane_settings_injection, param_settings)]
        if self.attach_service_call or self.detach_service_call:
            self.logger.debug('Using custom service calls')
            cmds.append(self._get_service_call_cmd(detach))
            return cmds
        if self._is_qualcomm_prototype:
            if self._ue_model in UEs_Screen_Wakeup and not adb.adb_is_screen_on(ue_sn=self._sn):
                cmds.append("{} {}".format(self._su_prefix, cmd_wakeup_screen))
                cmds.append("{} {}".format(self._su_prefix, cmd_swipe_up_screen))
            cmds.append("{} {} {}".format(self._su_prefix, cmd_raw_airplane_broadcast, param_broadcast))
            return cmds
        if not self._is_android_7_support_required():
            cmds.append("{} {}".format(cmd_raw_airplane_broadcast, param_broadcast))
            return cmds
        if self._is_rooted:
            cmds.extend(["{} {} {}".format(self._su_prefix, cmd_raw_airplane_broadcast, param_broadcast)])
            return cmds
        cmds.append(self._get_service_call_cmd())
        return cmds

    def _get_service_call_cmd(self, detach=False):
        configured_service_call = self._get_predefined_service_call(detach)
        if configured_service_call:
            return configured_service_call

        for ue_models in [SVC_CALL_14_UE_MODELS, SVC_CALL_15_UE_MODELS, SVC_CALL_16_UE_MODELS, SVC_CALL_17_UE_MODELS, SVC_CALL_25_UE_MODELS]:
            svc_call = self._get_service_call_by_ue_model_group(ue_models)
            if svc_call:
                return svc_call

        if any([model in self._ue_model.upper() for model in SVC_CALL_UE_MODELS_CPU]):
            # S10 "SM-G977U", S10 also "SM-G977n",S20+ "SM-G986U", S9 "SM-G960F", S20 Ultra "SM-G988U1", S20
            return self._get_service_call_by_cpu()

        if any([vendor in self._ue_model.upper() for vendor in SVC_CALL_28_VENDORS]):
            return self._get_raw_antenna_cmd(28)
        return self._get_raw_antenna_cmd(27)

    def _get_service_call_by_ue_model_group(self, ue_models):
        if any([model in self._ue_model.upper() for model in ue_models[0]]):
            return self._get_raw_antenna_cmd(ue_models[1])

    def _get_predefined_service_call(self, detach):
        if detach and self.detach_service_call:
            return self._get_raw_antenna_cmd(self.detach_service_call)
        if self.attach_service_call:
            return self._get_raw_antenna_cmd(self.attach_service_call)

    def _is_android_7_support_required(self):
        if isinstance(self._android_version, six.string_types):
            return self._is_android_7_support_required_legacy()

        return int(self._android_version) >= 23

    def _is_android_7_support_required_legacy(self):
        v_major = str(self._android_version).split('.')[0]
        if not v_major.isdigit():
            return True
        if int(v_major) >= 7:
            return True
        return False

    def _get_service_call_by_cpu(self):
        ue_cpu = self.ueman.get_ue_cpu().upper()
        if "EXYNOS" in ue_cpu:
            return self._get_raw_antenna_cmd(29)
        return self._get_raw_antenna_cmd(18)

    @staticmethod
    def _get_raw_antenna_cmd(service_call):
        return "{} {}".format(cmd_raw_antenna_trigger, service_call)
